<script setup lang="ts">
import {computed,onUnmounted,ref,shallowRef,watch} from 'vue';import {useApplication} from '../../application';import type {RecordingSession,RecordingArchiveStatus} from './recording-api';
const props=defineProps<{recording:RecordingSession}>(),{recordingApi,session}=useApplication(),status=shallowRef<RecordingArchiveStatus|null>(null),busy=ref(false),error=ref<string|null>(null);let generation=0,timer:ReturnType<typeof setTimeout>|null=null,deadline=0;
const names:Record<RecordingArchiveStatus['state'],string>={READY:'等待归档',RUNNING:'正在归档',RECONCILING:'正在核对结果',SUCCEEDED:'录音归档完成',FAILED:'归档失败，原分片保留',CANCELLED:'归档已取消',STALE:'归档状态已变化'};
const audio=computed(()=>status.value?.available?recordingApi.audioUrl(props.recording):null),retryable=computed(()=>status.value&&['FAILED','CANCELLED','STALE'].includes(status.value.state));
async function load(retry=false){if(busy.value)return;const turn=generation,actor=session.current.value?.actor.enterpriseId,recording={...props.recording};if(!actor)return;const active=()=>turn===generation&&actor===session.current.value?.actor.enterpriseId&&props.recording.sessionId===recording.sessionId;busy.value=true;error.value=null;try{const value=await(retry?recordingApi.retryArchive(recording):recordingApi.archive(recording));if(!active())return;status.value=value;if(!value.available&&['READY','RUNNING','RECONCILING'].includes(value.state)){if(Date.now()<deadline)timer=setTimeout(()=>{timer=null;void load();},1000);else error.value='归档仍未确认，请稍后刷新状态';}}catch(cause){if(active())error.value=cause instanceof Error?cause.message:'录音归档暂不可读取';}finally{if(active())busy.value=false;}}
function refresh(retry=false){if(timer)clearTimeout(timer);timer=null;deadline=Date.now()+180000;void load(retry);}
const stop=watch(()=>[session.current.value?.actor.enterpriseId,props.recording.sessionId],()=>{generation++;if(timer)clearTimeout(timer);timer=null;busy.value=false;status.value=null;error.value=null;refresh();},{immediate:true});onUnmounted(()=>{generation++;stop();if(timer)clearTimeout(timer);});
</script>
<template><section class="card mt16" aria-label="录音归档"><div class="card-h"><h2 class="card-t">{{status?names[status.state]:'正在读取录音归档'}}</h2><button class="btn sm ghost ml-a" :disabled="busy" @click="refresh()">刷新归档状态</button></div><div class="archive-body"><audio v-if="audio" :key="audio" :src="audio" controls preload="metadata" aria-label="录音归档回听" style="width:100%" @error="error='音频暂不可播放，请刷新登录和归档状态后重试'"></audio><p v-else class="small muted">采集已封存，录音分片继续保留。归档成功后可在此回听。</p><p v-if="audio" class="small muted mt12">全部录音段按采集顺序归档。</p><p v-if="error" class="ac-error mt12" role="alert">{{error}}</p><button v-if="retryable" class="btn sm mt12" :disabled="busy" @click="refresh(true)">重试录音归档</button></div></section></template>

<style scoped>.archive-body{padding:16px;}</style>
